function validate([n, conflictingPairs]) {
  if (n < 2 || n > 1e5) return 'n is between 2 and 10^5.';
  if (conflictingPairs.length < 1 || conflictingPairs.length > 2 * n) return 'conflictingPairs needs 1 to 2 * n pairs.';
  for (const pair of conflictingPairs) {
    if (pair.length !== 2) return 'Each conflicting pair has exactly two values.';
    if (pair[0] < 1 || pair[0] > n || pair[1] < 1 || pair[1] > n) return 'Pair values are between 1 and n.';
    if (pair[0] === pair[1]) return 'The two values of a pair must differ.';
  }
  return null;
}

