function maxSubarrays(n, conflictingPairs) {
  // pairsEndingAt[b] lists the smaller value of every pair whose larger value is b.
  const pairsEndingAt = Array.from({ length: n + 1 }, () => []);
  for (const [a, b] of conflictingPairs) {
    pairsEndingAt[Math.max(a, b)].push(Math.min(a, b));
  }
  const gain = new Array(n + 1).fill(0);
  let first = 0;
  let second = 0;
  let total = 0;
  let bestGain = 0;
  for (let right = 1; right <= n; right++) {
    for (const left of pairsEndingAt[right]) {
      if (left > first) {
        second = first;
        first = left;
      } else if (left > second) {
        second = left;
      }
    }
    total += right - first;
    gain[first] += first - second;
    bestGain = Math.max(bestGain, gain[first]);
  }
  return total + bestGain;
}

