function maxSubarrays(n, conflictingPairs) {
  // Try deleting each pair. A subarray starting at start may grow until it would hold
  // both values of a remaining pair, so count the allowed ends for every start.
  let best = 0;
  for (let skip = 0; skip < conflictingPairs.length; skip++) {
    let count = 0;
    for (let start = 1; start <= n; start++) {
      let stop = n + 1;
      conflictingPairs.forEach(([a, b], k) => {
        if (k !== skip && Math.min(a, b) >= start) stop = Math.min(stop, Math.max(a, b));
      });
      count += stop - start;
    }
    best = Math.max(best, count);
  }
  return best;
}

