function generate(rand, size) {
  const large = size === 'large';
  // Large inputs use either 2,000 mixed pairs, or a few long pairs on a long array (an answer usually beyond 2^31).
  const fewLong = large && rand() < 0.4;
  const n = fewLong ? 70000 + Math.floor(rand() * 30001) : large ? 1000 + Math.floor(rand() * 99001) : 2 + Math.floor(rand() * 9);
  const m = fewLong ? 1 + Math.floor(rand() * 5) : large ? 2000 : 1 + Math.floor(rand() * 2 * n);
  const pairs = [];
  for (let k = 0; k < m; k++) {
    let a, b;
    do {
      a = 1 + Math.floor(rand() * n);
      const reach = fewLong ? Math.floor(n / 2) + Math.floor(rand() * (n / 2)) : rand() < 0.5 ? 1 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * n);
      b = rand() < 0.5 ? a + reach : a - reach;
    } while (b < 1 || b > n || b === a);
    pairs.push(rand() < 0.5 ? [a, b] : [b, a]);
  }
  return [n, pairs];
}
